/** Shared job types, submission validation, and payload normalization. */

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** The public job representation returned by every endpoint that returns a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface FieldError {
  field: string;
  message: string;
}

export interface SubmissionPayload {
  input: string;
  steps: number;
  failAttempts: number;
}

export const MAX_INPUT_LENGTH = 1000;
export const MAX_STEPS = 20;
export const DEFAULT_STEPS = 5;
export const MAX_FAIL_ATTEMPTS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;
export const MAX_BODY_BYTES = 64 * 1024;
export const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

export interface RawSubmission {
  contentType: string | undefined;
  body: string;
  bodyTooLarge: boolean;
  idempotencyKey: string | undefined;
}

export type SubmissionOutcome =
  | { ok: true; payload: SubmissionPayload; idempotencyKey: string | undefined }
  | { ok: false; fields: FieldError[] };

/** True when the media type (ignoring parameters such as charset) is application/json. */
export function isJsonContentType(value: string | undefined): boolean {
  if (!value) return false;
  return value.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

const hasOwn = (obj: object, key: string): boolean => Object.prototype.hasOwnProperty.call(obj, key);

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function readInteger(obj: Record<string, unknown>, name: string, min: number, max: number, fallback: number, fields: FieldError[]): number {
  if (!hasOwn(obj, name)) return fallback;
  const value = obj[name];
  if (typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max) return value;
  fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}.` });
  return fallback;
}

/** Validates a submission completely before any database access; accumulates every field error. */
export function validateSubmission(raw: RawSubmission): SubmissionOutcome {
  const fields: FieldError[] = [];
  const bodyError = (message: string) => fields.push({ field: 'body', message });

  let obj: Record<string, unknown> | undefined;
  if (!isJsonContentType(raw.contentType)) {
    bodyError('Content-Type must be application/json.');
  } else if (raw.bodyTooLarge) {
    bodyError(`Request body must be at most ${MAX_BODY_BYTES} bytes.`);
  } else {
    let parsed: unknown;
    try {
      parsed = JSON.parse(raw.body);
    } catch {
      bodyError('Request body must be valid JSON.');
      parsed = undefined;
      obj = undefined;
    }
    if (parsed !== undefined || raw.body.trim() === 'null') {
      if (isPlainObject(parsed)) obj = parsed;
      else bodyError('Request body must be a JSON object.');
    }
  }

  if (obj) {
    for (const key of Object.keys(obj)) {
      if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
    }
    if (!hasOwn(obj, 'input')) {
      fields.push({ field: 'input', message: 'input is required.' });
    } else if (typeof obj.input !== 'string') {
      fields.push({ field: 'input', message: 'input must be a string.' });
    } else if (obj.input.length < 1 || obj.input.length > MAX_INPUT_LENGTH) {
      fields.push({ field: 'input', message: `input must be 1 to ${MAX_INPUT_LENGTH} characters.` });
    } else if (obj.input.trim() === '') {
      fields.push({ field: 'input', message: 'input must not be only whitespace.' });
    }
  }

  if (raw.idempotencyKey !== undefined && !IDEMPOTENCY_KEY_PATTERN.test(raw.idempotencyKey)) {
    fields.push({
      field: 'Idempotency-Key',
      message: 'Idempotency-Key must be 1 to 128 characters: letters, digits, "_" or "-".',
    });
  }

  if (fields.length > 0 || !obj) {
    return { ok: false, fields: fields.length > 0 ? fields : [{ field: 'body', message: 'Request body is invalid.' }] };
  }

  const steps = readInteger(obj, 'steps', 1, MAX_STEPS, DEFAULT_STEPS, fields);
  const failAttempts = readInteger(obj, 'failAttempts', 0, MAX_FAIL_ATTEMPTS, DEFAULT_FAIL_ATTEMPTS, fields);
  if (fields.length > 0) return { ok: false, fields };

  return {
    ok: true,
    payload: { input: obj.input as string, steps, failAttempts },
    idempotencyKey: raw.idempotencyKey,
  };
}

