import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase, serializeJob, transaction, type JobRow } from './db.ts';
import { MAX_BODY_BYTES, validateSubmission, type FieldError, type SubmissionPayload } from './jobs.ts';

/** The worker counts as up only if its heartbeat is at most this old. */
const HEARTBEAT_FRESH_MS = 3_000;
const SHUTDOWN_GRACE_MS = 2_000;
const SHUTDOWN_HARD_MS = 5_000;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const insertStmt = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, output, error, created_at, updated_at, idem_key, retry_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, ?, 0)`,
);
const byIdStmt = db.prepare('SELECT * FROM jobs WHERE id = ?');
const byKeyStmt = db.prepare('SELECT * FROM jobs WHERE idem_key = ?');
const listStmt = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const heartbeatStmt = db.prepare('SELECT at FROM heartbeat WHERE id = 1');

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], headers?: Record<string, string>): void {
  sendJson(res, status, { error: { code, message, ...(fields ? { fields } : {}) } }, headers);
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed for this path.', undefined, { allow: allowed.join(', ') });
}

function notFound(res: ServerResponse): void {
  sendError(res, 404, 'not_found', 'Not found.');
}

/** Reads the body up to MAX_BODY_BYTES. Larger bodies are drained and flagged, not buffered. */
function readBody(req: IncomingMessage): Promise<{ body: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
      } else if (!tooLarge) {
        chunks.push(chunk);
      }
    });
    req.on('end', () => resolve({ body: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { body, tooLarge } = await readBody(req);
  const headerKey = req.headers['idempotency-key'];
  const outcome = validateSubmission({
    contentType: req.headers['content-type'],
    body,
    bodyTooLarge: tooLarge,
    idempotencyKey: typeof headerKey === 'string' ? headerKey : undefined,
  });
  if (!outcome.ok) {
    sendError(res, 400, 'invalid_request', 'The submission is invalid.', outcome.fields);
    return;
  }

  const { payload, idempotencyKey } = outcome;
  const result = transaction(db, () => {
    if (idempotencyKey !== undefined) {
      const existing = byKeyStmt.get(idempotencyKey) as unknown as JobRow | undefined;
      if (existing) {
        if (samePayload(existing, payload)) return { status: 200 as const, row: existing };
        return { status: 409 as const, row: undefined };
      }
    }
    const now = new Date().toISOString();
    const id = randomUUID();
    insertStmt.run(id, payload.input, payload.steps, payload.failAttempts, now, now, idempotencyKey ?? null);
    const row = byIdStmt.get(id) as unknown as JobRow;
    return { status: 201 as const, row };
  });

  if (result.status === 409) {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, result.status, serializeJob(result.row));
}

function samePayload(row: JobRow, payload: SubmissionPayload): boolean {
  return row.input === payload.input && row.steps === payload.steps && row.fail_attempts === payload.failAttempts;
}

function handleHealth(res: ServerResponse): void {
  const row = heartbeatStmt.get() as { at: number } | undefined;
  const up = row !== undefined && Date.now() - Number(row.at) <= HEARTBEAT_FRESH_MS;
  sendJson(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    return handleHealth(res);
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      const rows = listStmt.all() as unknown as JobRow[];
      sendJson(res, 200, { jobs: rows.map(serializeJob) });
      return;
    }
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }

  const detail = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (detail) {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    let id: string;
    try {
      id = decodeURIComponent(detail[1]!);
    } catch {
      return notFound(res);
    }
    const row = byIdStmt.get(id) as unknown as JobRow | undefined;
    if (!row) return notFound(res);
    sendJson(res, 200, serializeJob(row));
    return;
  }

  notFound(res);
}

const server = createServer((req, res) => {
  route(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) {
      sendError(res, 500, 'internal_error', 'Unexpected server error.');
    } else {
      res.end();
    }
  });
});

let dbClosed = false;
let shuttingDown = false;

function closeAndExit(): void {
  if (!dbClosed) {
    dbClosed = true;
    db.close();
  }
  process.exit(0);
}

function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  // Stop accepting connections; let in-flight handlers finish within the grace period.
  server.close(() => closeAndExit());
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), SHUTDOWN_GRACE_MS).unref();
  setTimeout(closeAndExit, SHUTDOWN_HARD_MS);
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, shutdown);

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

