import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

/** Time per processing step. */
const STEP_MS = 100;
/** How often an idle worker looks for work. */
const POLL_MS = 100;
const HEARTBEAT_MS = 500;
/** Delay before a failed attempt is retried. */
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;

const db = openDatabase();

const nextStmt = db.prepare(
  `SELECT * FROM jobs
   WHERE status = 'running' OR (status = 'queued' AND retry_at <= ?)
   ORDER BY (status = 'running') DESC, seq ASC
   LIMIT 1`,
);
const byIdStmt = db.prepare('SELECT * FROM jobs WHERE id = ?');
const claimStmt = db.prepare(
  `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, output = NULL, error = NULL,
     retry_at = 0, updated_at = ? WHERE id = ? AND status = 'queued'`,
);
const resetRunningStmt = db.prepare(`UPDATE jobs SET completed = 0, updated_at = ? WHERE id = ? AND status = 'running'`);
const progressStmt = db.prepare(`UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`);
const retryStmt = db.prepare(
  `UPDATE jobs SET status = 'queued', completed = 0, retry_at = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const failStmt = db.prepare(
  `UPDATE jobs SET status = 'failed', completed = 0, output = NULL, error = 'transient failure', updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
const completeStmt = db.prepare(
  `UPDATE jobs SET status = 'completed', completed = steps, output = ?, error = NULL, updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
const heartbeatStmt = db.prepare(
  'INSERT INTO heartbeat (id, at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET at = excluded.at',
);
const clearHeartbeatStmt = db.prepare('DELETE FROM heartbeat');

let stopping = false;
let lastBeat = 0;

function beat(force = false): void {
  const now = Date.now();
  if (!force && now - lastBeat < HEARTBEAT_MS) return;
  heartbeatStmt.run(now);
  lastBeat = now;
}

const nowIso = (): string => new Date().toISOString();

/**
 * Runs one attempt of a job that is already marked running. The attempt number is the job's
 * persisted `attempts`, so an interrupted attempt replays with the same number.
 */
async function runAttempt(job: JobRow): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    // Simulated transient failure at the first step, before any progress is recorded.
    await sleep(STEP_MS);
    if (job.attempts >= MAX_ATTEMPTS) {
      failStmt.run(nowIso(), job.id);
      console.log(`job ${job.id} failed after ${job.attempts} attempts`);
    } else {
      retryStmt.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
      console.log(`job ${job.id} attempt ${job.attempts} failed; retrying`);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    progressStmt.run(step, nowIso(), job.id);
    beat();
  }
  // Output, status, and final progress are committed together in one statement.
  completeStmt.run(job.input.toUpperCase(), nowIso(), job.id);
  console.log(`job ${job.id} completed`);
}

async function main(): Promise<void> {
  beat(true);
  console.log('worker started');

  while (!stopping) {
    beat();
    const row = nextStmt.get(Date.now()) as unknown as JobRow | undefined;
    if (!row) {
      await sleep(POLL_MS);
      continue;
    }
    try {
      // A running row can only be left over from an interrupted worker: resume its attempt
      // from step zero without counting it as another attempt.
      if (row.status === 'running') {
        resetRunningStmt.run(nowIso(), row.id);
      } else {
        claimStmt.run(nowIso(), row.id);
      }
      const job = byIdStmt.get(row.id) as unknown as JobRow;
      await runAttempt(job);
    } catch (err) {
      console.error('processing error:', err);
      await sleep(POLL_MS);
    }
  }
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

await main();
try {
  clearHeartbeatStmt.run();
} catch {
  // the heartbeat simply expires if it cannot be cleared
}
db.close();
console.log('worker stopped');

